   270	
   271	/****************************************************************************
   272	 * Name: battery_read_raw
   273	 *
   274	 * Description:
   275	 *   One blocking conversion through the generic ADC character driver. Returns
   276	 *   the value in the driver's own millivolt scale, before the divider is
   277	 *   applied.
   278	 *
   279	 ****************************************************************************/
   280	
   281	static int battery_read_raw(int *out_mv)
   282	{
   283	  struct adc_msg_s sample;
   284	  ssize_t nread;
   285	  int ret;
   286	
   287	  if (g_fd < 0)
   288	    {
   289	      g_fd = open(BATTERY_ADC_DEV, O_RDONLY);
   290	      if (g_fd < 0)
   291	        {
   292	          return -errno;
   293	        }
   294	    }
   295	
   296	  ret = ioctl(g_fd, ANIOC_TRIGGER, 0);
   297	  if (ret < 0)
   298	    {
   299	      ret = -errno;
   300	      goto errout;
   301	    }
   302	
   303	  memset(&sample, 0, sizeof(sample));
   304	  nread = read(g_fd, &sample, sizeof(sample));
   305	  if (nread != (ssize_t)sizeof(sample))
   306	    {
   307	      ret = nread < 0 ? -errno : -EIO;
   308	      goto errout;
   309	    }
   310	
   311	  /* Drop implausible conversions instead of averaging them in. The handle
   312	   * stays open here on purpose: the device is fine, the sample is not, and
   313	   * reopening costs another ADC setup for nothing.
   314	   */
   315	
   316	  if (sample.am_data < BATTERY_PIN_MIN_MV ||
   317	      sample.am_data > BATTERY_PIN_MAX_MV)
   318	    {
   319	      return -ERANGE;
   320	    }
   321	
   322	  *out_mv = (int)sample.am_data;
   323	  return OK;
   324	
   325	errout:
   326	  /* Drop the handle so the next call reopens it; the ADC device itself is
   327	   * registered once at boot and is never torn down.
   328	   */
   329	
   330	  close(g_fd);
   331	  g_fd = -1;
   332	  return ret;
   333	}
   334	
   335	/****************************************************************************
   336	 * Public Functions
   337	 ****************************************************************************/
   338	
   339	/****************************************************************************
   340	 * Name: battery_worker
   341	 *
   342	 * Description:
   343	 *   Sampling lives on its own thread because one conversion blocks for about
   344	 *   256 ms: sf32lb_adc.c averages ADC_AVERAGE_COUNT (20) samples with a fixed
   345	 *   HAL_Delay_us(10 * 1000) between them. Doing that on the LVGL thread would
   346	 *   freeze the UI for a quarter second every period.
   347	 *
   348	 *   The spawn priority is BATTERY_PRIORITY, which has to sit genuinely below
   349	 *   motion (80) and light (90) -- see the comment on that macro. This thread
   350	 *   touches only the ADC, so it cannot delay the sensor bus, but the spin
   351	 *   inside HAL_Delay_us() means it can delay anything below it if it is
   352	 *   allowed to run high.
   353	 *
   354	 ****************************************************************************/
   355	
   356	static void *battery_worker(void *arg)
   357	{
   358	  (void)arg;
   359	
   360	  for (;;)
   361	    {
   362	      int raw;
   363	      int ret;
   364	
   365	      ret = battery_read_raw(&raw);
   366	      if (ret >= 0)
   367	        {
   368	          g_raw_mv = raw;
   369	          g_vbat_mv = raw * BATTERY_DIVIDER_X100 / 100;
   370	          battery_hist_push(g_vbat_mv);
   371	          g_percent = battery_percent_from_mv(battery_hist_average());
   372	          g_available = true;
   373	
   374	          /* Print every sample. At 60 s intervals this is quiet, and it is
   375	           * what makes a battery plug/unplug visible within a minute.
   376	           */
   377	
   378	          printf("BAT: raw=%d mV vbat=%d mV soc=%d%% (n=%d)\n",
   379	                 g_raw_mv, g_vbat_mv, g_percent, g_hist_len);
   380	          g_reported_once = true;
   381	        }
   382	      else if (ret == -ERANGE)
   383	        {
   384	          /* Logged rather than swallowed: a stream of these means the ADC is
   385	           * timing out, and the gauge would otherwise just look stuck.
   386	           */
   387	
   388	          printf("BAT: implausible sample dropped\n");
   389	        }
   390	
   391	      usleep(BATTERY_PERIOD_MS * 1000);
   392	    }
   393	
   394	  return NULL;
   395	}
   396	
   397	void ai_watch_battery_init(void)
   398	{
   399	#if !BATTERY_SAMPLING_ENABLE
   400	  /* Isolation build: report nothing, touch nothing. The Home gauge then
   401	   * shows "--%" because ai_watch_battery_percent() returns -1.
   402	   */
   403	
   404	  printf("BAT: sampling disabled (BLE isolation build)\n");
   405	  return;
   406	#else
   407	  pthread_attr_t attr;
   408	  struct sched_param param;
   409	  uint32_t t0 = battery_now_ms();
   410	  int ret;
   411	
   412	  /* First conversion here, on the caller's thread, so the very first screen
   413	   * can already show a value. This happens before the UI exists, so the
   414	   * 256 ms cost is invisible.
   415	   */
   416	
   417	  ret = battery_read_raw(&g_raw_mv);
   418	  if (ret < 0)
   419	    {
   420	      printf("BAT: %s open/read failed: %d\n", BATTERY_ADC_DEV, ret);
   421	      return;
   422	    }
   423	
   424	  g_vbat_mv = g_raw_mv * BATTERY_DIVIDER_X100 / 100;
   425	  battery_hist_push(g_vbat_mv);
   426	  g_percent = battery_percent_from_mv(battery_hist_average());
   427	  g_available = true;
   428	
   429	  printf("BAT: adc=%d mV raw, x%u.%02u -> %d mV, %d%% (%lu ms)\n",
   430	         g_raw_mv,
   431	         (unsigned int)(BATTERY_DIVIDER_X100 / 100),
   432	         (unsigned int)(BATTERY_DIVIDER_X100 % 100),
   433	         g_vbat_mv, g_percent,
   434	         (unsigned long)(battery_now_ms() - t0));
   435	
   436	  if (g_worker_started)
   437	    {
   438	      return;
   439	    }
   440	
   441	  pthread_attr_init(&attr);
   442	  pthread_attr_setstacksize(&attr, 4096);
   443	  pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);
   444	  param.sched_priority = BATTERY_PRIORITY;
   445	  pthread_attr_setschedparam(&attr, &param);
   446	  pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
   447	
   448	  if (pthread_create(&g_worker, &attr, battery_worker, NULL) == 0)
   449	    {
   450	      g_worker_started = true;
   451	    }
   452	  else
   453	    {
   454	      printf("BAT: worker create failed\n");
   455	    }
   456	
   457	  pthread_attr_destroy(&attr);
   458	#endif /* BATTERY_SAMPLING_ENABLE */
   459	}
   460	
   461	void ai_watch_battery_poll(void)
   462	{
   463	  /* Nothing to do: sampling runs on the worker. The hook is kept so the main
   464	   * loop does not have to know that.
   465	   */
   466	}
