   121	/****************************************************************************
   122	 * Private Functions
   123	 ****************************************************************************/
   124	
   125	/****************************************************************************
   126	 * Name: light_read_regs
   127	 *
   128	 * Description:
   129	 *   Two-phase register read: address phase, then a data phase with the
   130	 *   sensor's own pointer auto-incrementing. Deliberately not using the
   131	 *   I2C_M_NOSTOP/I2C_M_NOSTART single-transfer form: the two-phase pattern
   132	 *   is what the in-tree IMU driver has always exercised on this SoC.
   133	 *
   134	 ****************************************************************************/
   135	
   136	static int light_read_regs(uint8_t reg, FAR uint8_t *buf, size_t len)
   137	{
   138	  struct i2c_msg_s msg;
   139	  struct i2c_transfer_s xfer;
   140	  int ret;
   141	
   142	  if (g_i2c_fd < 0)
   143	    {
   144	      return -ENODEV;
   145	    }
   146	
   147	  msg.addr      = LTR303_ADDR;
   148	  msg.frequency = LIGHT_I2C_FREQ;
   149	  msg.flags     = 0;
   150	  msg.buffer    = &reg;
   151	  msg.length    = 1;
   152	
   153	  xfer.msgv = &msg;
   154	  xfer.msgc = 1;
   155	
   156	  ret = ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)(uintptr_t)&xfer);
   157	  if (ret < 0)
   158	    {
   159	      return ret;
   160	    }
   161	
   162	  msg.flags  = I2C_M_READ;
   163	  msg.buffer = buf;
   164	  msg.length = len;
   165	
   166	  ret = ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)(uintptr_t)&xfer);
   167	  if (ret < 0)
   168	    {
   169	      return ret;
   170	    }
   171	
   172	  return OK;
   173	}
   174	
   175	/****************************************************************************
   176	 * Name: light_write_reg
   177	 ****************************************************************************/
   178	
   179	static int light_write_reg(uint8_t reg, uint8_t value)
   180	{
   181	  struct i2c_msg_s msg;
   182	  struct i2c_transfer_s xfer;
   183	  uint8_t buf[2];
   184	  int ret;
   185	
   186	  if (g_i2c_fd < 0)
   187	    {
   188	      return -ENODEV;
   189	    }
   190	
   191	  buf[0] = reg;
   192	  buf[1] = value;
   193	
   194	  msg.addr      = LTR303_ADDR;
   195	  msg.frequency = LIGHT_I2C_FREQ;
   196	  msg.flags     = 0;
   197	  msg.buffer    = buf;
   198	  msg.length    = 2;
   199	
   200	  xfer.msgv = &msg;
   201	  xfer.msgc = 1;
   202	
   203	  ret = ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)(uintptr_t)&xfer);
   204	  return ret < 0 ? ret : OK;
   205	}
