   207	/****************************************************************************
   208	 * Name: light_apply
   209	 *
   210	 * Description:
   211	 *   Push a percentage to the panel. Also used at boot to replace the
   212	 *   panel's power-on default.
   213	 *
   214	 ****************************************************************************/
   215	
   216	static void light_apply(int percent)
   217	{
   218	  if (percent < 1)
   219	    {
