   236	/****************************************************************************
   237	 * Name: light_level_for_lux
   238	 ****************************************************************************/
   239	
   240	static int light_level_for_lux(uint32_t lux)
   241	{
   242	  unsigned i;
   243	  int percent = g_light_bands[0].percent;
   244	
   245	  for (i = 0; i < LIGHT_NBANDS; i++)
   246	    {
   247	      if (lux >= g_light_bands[i].lux)
   248	        {
