   255	
   256	/****************************************************************************
   257	 * Name: light_measure
   258	 *
   259	 * Description:
   260	 *   One ALS conversion. Returns the computed lux, or a negative errno.
   261	 *
   262	 *   CH0 counts visible+IR, CH1 counts IR only. The ratio picks the
   263	 *   compensation curve, which is the standard LTR-303 formula for gain 1x
   264	 *   and 100 ms integration.
   265	 *
   266	 ****************************************************************************/
   267	
   268	static int light_measure(FAR uint32_t *lux)
   269	{
   270	  uint8_t raw[4];
   271	  uint16_t ch1;
   272	  uint16_t ch0;
   273	  float ratio;
   274	  float value;
   275	  int ret;
   276	
   277	  ret = light_read_regs(LTR303_DATA_CH1_0, raw, sizeof(raw));
   278	  if (ret < 0)
   279	    {
   280	      return ret;
   281	    }
   282	
   283	  ch1 = (uint16_t)((raw[1] << 8) | raw[0]);
   284	  ch0 = (uint16_t)((raw[3] << 8) | raw[2]);
   285	
   286	  if (ch0 == 0 && ch1 == 0)
   287	    {
   288	      *lux = 0;
   289	      return OK;
   290	    }
   291	
   292	  ratio = (float)ch1 / (float)(ch0 + ch1);
   293	
   294	  if (ratio < 0.45f)
   295	    {
   296	      value = 1.7743f * ch0 + 1.1059f * ch1;
   297	    }
   298	  else if (ratio < 0.64f)
   299	    {
   300	      value = 4.2785f * ch0 - 1.9548f * ch1;
   301	    }
   302	  else if (ratio < 0.85f)
   303	    {
   304	      value = 0.5926f * ch0 + 0.1185f * ch1;
   305	    }
   306	  else
   307	    {
   308	      value = 0.0f;
   309	    }
   310	
   311	  *lux = (uint32_t)(value + 0.5f);
   312	  return OK;
   313	}
   314	
   315	/****************************************************************************
   316	 * Name: light_thread
   317	 ****************************************************************************/
   318	
   319	static FAR void *light_thread(FAR void *arg)
   320	{
   321	  int candidate = -1;
   322	  unsigned stable = 0;
   323	
   324	  (void)arg;
   325	
   326	  for (;;)
   327	    {
   328	      uint32_t lux;
   329	      int level;
   330	
   331	      usleep(LIGHT_PERIOD_MS * 1000);
   332	
   333	      if (!g_present)
   334	        {
   335	          continue;
   336	        }
   337	
   338	      if (light_measure(&lux) < 0)
   339	        {
   340	          continue;
   341	        }
   342	
   343	      g_lux = lux;
   344	
   345	      if (!g_auto)
   346	        {
   347	          continue;
   348	        }
   349	
   350	      level = light_level_for_lux(lux);
   351	
   352	      /* Require two consecutive samples in the same band so a hand passing
   353	       * over the sensor does not make the panel flash.
   354	       */
   355	
   356	      if (level == candidate)
   357	        {
   358	          stable++;
   359	        }
   360	      else
   361	        {
   362	          candidate = level;
   363	          stable = 1;
   364	        }
   365	
   366	      if (stable >= 2 && level != g_level && level != g_pending_level)
   367	        {
   368	          g_pending_level = level;
   369	        }
   370	    }
   371	
   372	  return NULL;
   373	}
