   382	  uint8_t part;
   383	  uint8_t manu;
   384	  int ret;
   385	
   386	  g_i2c_fd = open(LIGHT_I2C_DEV, O_RDWR | O_CLOEXEC);
   387	  if (g_i2c_fd < 0)
   388	    {
   389	      printf("LIGHT: %s open failed: %d\n", LIGHT_I2C_DEV, errno);
