   399	  /* Dump the identification page first: this is the gate for the whole
   400	   * feature. If the IDs do not match, nothing else is touched.
   401	   */
   402	
   403	  ret = light_read_regs(LTR303_ALS_CONTR, dump, sizeof(dump));
