 316	 * Name: light_thread
 317	 ****************************************************************************/
 318	
 319	static FAR void *light_thread(FAR void *arg)
 320	{
 321	  int candidate = -1;
 322	  unsigned stable = 0;
 323	
 324	  (void)arg;
 325	
 326	  for (;;)
 327	    {
 328	      uint32_t lux;
 329	      int level;
 330	
 331	      usleep(LIGHT_PERIOD_MS * 1000);
 332	
 333	      if (!g_present)
 334	        {
 335	          continue;
 336	        }
 337	
 338	      if (light_measure(&lux) < 0)
 339	        {
 340	          continue;
 341	        }
 342	
 343	      g_lux = lux;
 344	
 345	      if (!g_auto)
 346	        {
 347	          continue;
 348	        }
 349	
 350	      level = light_level_for_lux(lux);
 351	
 352	      /* Require two consecutive samples in the same band so a hand passing
 353	       * over the sensor does not make the panel flash.
 354	       */
 355	
 356	      if (level == candidate)
 357	        {
 358	          stable++;
 359	        }
 360	      else
 361	        {
 362	          candidate = level;
 363	          stable = 1;
 364	        }
 365	
 366	      if (stable >= 2 && level != g_level && level != g_pending_level)
 367	        {
 368	          g_pending_level = level;
 369	        }
 370	    }
 371	
 372	  return NULL;
 373	}
