 387	
 388	  g_i2c_fd = open(LIGHT_I2C_DEV, O_RDWR | O_CLOEXEC);
 389	  if (g_i2c_fd < 0)
 390	    {
 391	      printf("LIGHT: %s open failed: %d\n", LIGHT_I2C_DEV, errno);
 392	      return -errno;
 393	    }
 394	
