 398	      printf("LIGHT: %s open failed: %d\n", LIGHT_LCD_DEV, errno);
 399	    }
 400	
 401	  /* Dump the identification page first: this is the gate for the whole
 402	   * feature. If the IDs do not match, nothing else is touched.
 403	   */
 404	
 405	  ret = light_read_regs(LTR303_ALS_CONTR, dump, sizeof(dump));
 406	  if (ret < 0)
 407	    {
 408	      printf("LIGHT: no answer at 0x%02x (%d)\n", LTR303_ADDR, ret);
 409	      return ret;
 410	    }
 411	
 412	  printf("LIGHT: 0x80..0x8F =");
 413	  for (int i = 0; i < (int)sizeof(dump); i++)
 414	    {
 415	      printf(" %02x", dump[i]);
 416	    }
 417	
 418	  printf("\n");
 419	
 420	  part = dump[LTR303_PART_ID - LTR303_ALS_CONTR];
 421	  manu = dump[LTR303_MANU_ID - LTR303_ALS_CONTR];
 422	
 423	  if (part != LTR303_PART_ID_VAL || manu != LTR303_MANU_ID_VAL)
 424	    {
 425	      printf("LIGHT: unexpected IDs part=0x%02x manu=0x%02x, disabled\n",
 426	             part, manu);
 427	      return -ENODEV;
 428	    }
 429	
 430	  printf("LIGHT: LTR-303ALS-01 detected (part=0x%02x manu=0x%02x)\n",
 431	         part, manu);
 432	
 433	  g_present = true;
 434	
 435	  /* Enable the ALS: active mode, gain 1x, 100 ms integration, 500 ms repeat */
 436	
 437	  ret = light_write_reg(LTR303_MEAS_RATE, LTR303_MEAS_500MS);
 438	  if (ret >= 0)
 439	    {
 440	      ret = light_write_reg(LTR303_ALS_CONTR, LTR303_CONTR_ACTIVE);
 441	    }
 442	
 443	  if (ret < 0)
 444	    {
 445	      printf("LIGHT: enable failed: %d\n", ret);
 446	      g_present = false;
 447	      return ret;
 448	    }
 449	
 450	  usleep(LIGHT_SETTLE_MS * 1000);
 451	
 452	  pthread_attr_init(&attr);
 453	  pthread_attr_setstacksize(&attr, LIGHT_STACKSIZE);
 454	  pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);
 455	  param.sched_priority = LIGHT_PRIORITY;
 456	  pthread_attr_setschedparam(&attr, &param);
 457	
 458	  if (pthread_create(&g_thread, &attr, light_thread, NULL) == 0)
 459	    {
 460	      g_thread_running = true;
 461	    }
 462	  else
 463	    {
 464	      printf("LIGHT: thread create failed\n");
 465	    }
 466	
