   751	 ****************************************************************************/
   752	
   753	void ai_watch_ble_process(void)
   754	{
   755	  struct ai_watch_ble_bsp_timesync_s sync;
   756	  uint8_t cmd[AI_WATCH_BLE_CMD_MAX];
   757	  size_t len;
   758	
   759	  /* Deliver a pending validated TimeSync: RTC gets UTC, the timezone
   760	   * offset is remembered for display only.
   761	   */
   762	
   763	  if (ai_watch_ble_bsp_take_timesync(&sync))
   764	    {
   765	      ai_ble_apply_timesync(&sync);
   766	    }
   767	
   768	  /* Drain all queued Command frames */
   769	
   770	  while ((len = ai_watch_ble_bsp_take_command(cmd, sizeof(cmd))) > 0)
   771	    {
   772	      ai_ble_parse_command(cmd, len);
   773	    }
   774	
   775	  /* Raise banners for reminders whose trigger time just passed */
   776	
   777	  ai_ble_check_due();
   778	
   779	  /* Controller self-heal: recover hardware-error events and HCI command
   780	   * timeouts outside the controller RX/command callback context. */
   781	
   782	  if (ai_watch_ble_bsp_take_controller_fault())
   783	    {
   784	      s_initfail_tries = 0;
   785	      s_initfail_next.tv_sec = 0;
   786	#ifdef CONFIG_AI_WATCH_ROMDUMP
   787	      {
   788	        extern void ai_watch_reg_sampler_dump_ring(const char *tag);
   789	        extern void ai_watch_romdump_run_lps(void);
   790	        extern void ai_watch_romdump_run_regs(void);
   791	
   792	        /* r5 sampler ring FIRST (timeline before the fault), then the
   793	         * LPSYS window (assert record, patch hooks, cfg), then the
   794	         * register blocks - all while the failed controller is still
   795	         * up; recover() tears the LCPU down right after this.
   796	         *
   797	         * Full LPS dumps are rate-limited to the first two faults per
   798	         * boot: the wedge is fully characterized by now (r7/r8: hook
   799	         * independent, opcode agnostic) and each 2x64 KiB hex dump
   800	         * freezes the watch for seconds in front of the user.  The
   801	         * sampler ring and the fast register blocks stay on every
   802	         * fault - they are cheap and catch anything new. */
   803	
   804	        static int s_fault_full_dumps;
   805	
   806	        ai_watch_reg_sampler_dump_ring("fault");
   807	        if (s_fault_full_dumps < 2)
   808	          {
   809	            s_fault_full_dumps++;
   810	            ai_watch_romdump_run_lps();
   811	          }
   812	        ai_watch_romdump_run_regs();
   813	      }
   814	#endif
   815	      ai_watch_ble_bsp_recover();
   816	      return;
   817	    }
   818	
   819	  /* INIT_FAILED auto-recovery covers initialization failures that do not
   820	   * produce a Hardware Error or command-timeout callback. The retry is
   821	   * deliberately UNBOUNDED: the watch runs on a battery and cannot be
   822	   * power-cycled on site, so the old 5-attempt cap turned a transient
   823	   * bring-up failure into a radio that stayed silent until the battery
   824	   * died. The interval instead escalates to 5 min, which keeps the HCI
   825	   * load of a permanently broken controller negligible. Reaching a
   826	   * link-active state or toggling the switch restarts the ladder. OFF is
   827	   * deliberately NOT a reset because recover() passes through it during
   828	   * the asynchronous re-bring-up. */
   829	
   830	  {
   831	    enum ai_watch_ble_bsp_state_e state = ai_watch_ble_get_state();
   832	
   833	    if (state == AI_WATCH_BLE_BSP_ADVERTISING ||
   834	        state == AI_WATCH_BLE_BSP_CONNECTED ||
   835	        state == AI_WATCH_BLE_BSP_DISCONNECTED)
   836	      {
   837	        s_initfail_tries = 0;
   838	        s_initfail_next.tv_sec = 0;
   839	      }
   840	    else if (state == AI_WATCH_BLE_BSP_INIT_FAILED)
   841	      {
   842	        struct timespec now;
   843	        uint32_t backoff_s;
   844	
   845	        clock_gettime(CLOCK_MONOTONIC, &now);
   846	
   847	        if (s_initfail_next.tv_sec == 0)
   848	          {
   849	            /* first sighting: give the bring-up 10 s to settle before
   850	             * the first attempt (monotonic 0 only before scheduling) */
   851	
   852	            s_initfail_next = now;
   853	            s_initfail_next.tv_sec += AI_WATCH_BLE_INITFAIL_FIRST_S;
   854	          }
   855	        else if (now.tv_sec >= s_initfail_next.tv_sec)
   856	          {
   857	            if (s_initfail_tries < 1000000)
   858	              {
   859	                s_initfail_tries++;
   860	              }
   861	
   862	            backoff_s = ai_ble_initfail_backoff(s_initfail_tries);
   863	            s_initfail_next = now;
   864	            s_initfail_next.tv_sec += backoff_s;
   865	            syslog(LOG_WARNING,
   866	                   "aiwatch-ble: INIT_FAILED, auto-recover attempt %d"
   867	                   " (next in %lu s)\n",
   868	                   s_initfail_tries, (unsigned long)backoff_s);
   869	            ai_watch_ble_bsp_recover();
   870	            return;
   871	          }
   872	      }
   873	  }
   874	
   875	  /* Auto-reconnect: after a link loss, retry re-advertising once per
   876	   * second from this (application) thread until it succeeds - the
   877	   * bridge cannot run the HCI command sequence reliably from its RX
   878	   * context, and the host does not auto-resume ONE_TIME advertising.
   879	   */
   880	
   881	  if (ai_watch_ble_get_state() == AI_WATCH_BLE_BSP_DISCONNECTED)
   882	    {
   883	      static struct timespec next_retry;
   884	      struct timespec now;
   885	
   886	      clock_gettime(CLOCK_MONOTONIC, &now);
   887	
   888	      if (now.tv_sec >= next_retry.tv_sec)
   889	        {
   890	          ai_watch_ble_bsp_resume_advertising();
   891	          next_retry = now;
   892	          next_retry.tv_sec += 1;
   893	        }
   894	    }
   895	}
